-- supabase/sql/functions/jobs/acquire_lease.sql
-- ---------------------------------------------------------------------------
-- The lease.
--
-- One row per job name (0006). Taking it is one statement: an insert that
-- turns into an update only when the previous lease has lapsed, so two
-- callers racing for it cannot both win — the row lock decides, not the
-- clock they each read.
-- ---------------------------------------------------------------------------

create or replace function jobs.acquire_lease(p_name text, p_ttl interval, p_holder text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  acquired boolean;
begin
  if p_ttl <= interval '0' then
    raise exception 'lease ttl must be positive' using errcode = 'check_violation';
  end if;

  insert into jobs.cron_leases as l (name, leased_until, holder, last_started_at)
  values (p_name, now() + p_ttl, p_holder, now())
  on conflict (name) do update
    set leased_until = excluded.leased_until,
        holder = excluded.holder,
        last_started_at = excluded.last_started_at
    where l.leased_until is null or l.leased_until < now()
  returning true into acquired;

  return coalesce(acquired, false);
end;
$$;

comment on function jobs.acquire_lease(text, interval, text) is
  'True when the caller now holds the named lease until now() + ttl. False while somebody else holds it. One statement, so a race has one winner.';

revoke all on function jobs.acquire_lease(text, interval, text) from public;
revoke all on function jobs.acquire_lease(text, interval, text) from anon, authenticated;
grant execute on function jobs.acquire_lease(text, interval, text) to service_role;

-- supabase/sql/functions/jobs/add_daypart_counts.sql
create or replace function jobs.add_daypart_counts(p_a jsonb, p_b jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_object_agg(k, coalesce((p_a ->> k)::integer, 0) + coalesce((p_b ->> k)::integer, 0))
  from unnest(array[
    'weekday_morning', 'weekday_afternoon', 'weekday_evening',
    'weekend_morning', 'weekend_afternoon', 'weekend_evening'
  ]) as k;
$$;

revoke all on function jobs.add_daypart_counts(jsonb, jsonb) from public;
revoke all on function jobs.add_daypart_counts(jsonb, jsonb) from anon, authenticated;

-- supabase/sql/functions/jobs/carries_content.sql
-- ---------------------------------------------------------------------------
-- Non-negotiable 8, as a function.
--
-- Three tables here hold free-form JSON that is read by the dispatcher, the
-- notification pipeline and analytics, and none of them may be handed a
-- name, an email, a note, a title or a token. This walks the whole document —
-- objects inside arrays inside objects — because a check that looks only at
-- the top level is a promise about the shape the writer happened to use, and
-- `{"context": {"email": …}}` is a payload somebody will write in good faith.
--
-- Keys are matched by *fragment*, not by name: `recipient_email` and
-- `event_title` are the same leak with a prefix. The fragments are
-- `FORBIDDEN_PAYLOAD_KEYS` in packages/contracts/analytics.ts — the same list
-- the analytics catalogue test applies — rendered here by
-- scripts/gen-events.mjs, so the two cannot drift.
--
-- And values are checked, not only keys, because `{"value": "a@b.com"}` has
-- an innocent key. A string in one of these documents is an id, an instant,
-- an enum or a zone name — never words. So every string leaf must be at most
-- 40 characters of `[A-Za-z0-9_./:+-]`: no `@` (an address), no space (a
-- sentence), nothing a 256-bit token fits in. It cannot tell a one-word note
-- from an enum; it can refuse everything the invariant actually names.
-- ---------------------------------------------------------------------------

create or replace function jobs.carries_content(p_document jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  with recursive nodes (node) as (
    select p_document
    union all
    select child
    from nodes,
    lateral (
      select value from jsonb_each(case when jsonb_typeof(node) = 'object' then node else '{}'::jsonb end)
      union all
      select value from jsonb_array_elements(case when jsonb_typeof(node) = 'array' then node else '[]'::jsonb end)
    ) as children (child)
  )
  select exists (
    select 1
    from nodes,
      jsonb_object_keys(case when jsonb_typeof(node) = 'object' then node else '{}'::jsonb end) as k,
      unnest(
-- BEGIN GENERATED: forbidden key fragments (scripts/gen-events.mjs)
    array['name', 'email', 'note', 'token', 'title', 'secret', 'address', 'phone', 'message']
-- END GENERATED: forbidden key fragments
      ) as fragment
    where lower(k) like '%' || fragment || '%'
  )
  or exists (
    select 1 from nodes
    where jsonb_typeof(node) = 'string'
      and not ((node #>> '{}') ~ '^[A-Za-z0-9_./:+-]{1,40}$')
  );
$$;

comment on function jobs.carries_content(jsonb) is
  'True when any object at any depth carries a key naming a person, an address, a note, a title or a token, or any string value that is not an id, an instant, an enum or a zone. The check constraint on outbox, audit_log and analytics.events.';

revoke all on function jobs.carries_content(jsonb) from public;
revoke all on function jobs.carries_content(jsonb) from anon, authenticated;
grant execute on function jobs.carries_content(jsonb) to service_role;

-- supabase/sql/functions/jobs/daypart_counts.sql
-- The counts a set of responses contributes — computed over the windows that
-- are about to go, and *added* to what the summary already holds. The
-- summary is a running total across retention runs: a member whose answers
-- cross the twelve-month line on different nights must not end up with only
-- the last of them.

create or replace function jobs.daypart_counts(p_response_ids uuid[])
returns jsonb
language sql
stable
set search_path = ''
as $$
  with parts as (
    select
      case when extract(isodow from (w.starts_at at time zone p.time_zone)::date) in (6, 7)
        then 'weekend' else 'weekday' end as prefix,
      extract(hour from (w.starts_at at time zone p.time_zone))::integer * 60
        + extract(minute from (w.starts_at at time zone p.time_zone))::integer as start_min,
      case
        when (w.ends_at at time zone p.time_zone)::date = (w.starts_at at time zone p.time_zone)::date
        then extract(hour from (w.ends_at at time zone p.time_zone))::integer * 60
          + extract(minute from (w.ends_at at time zone p.time_zone))::integer
        else extract(hour from (w.ends_at at time zone p.time_zone))::integer * 60
          + extract(minute from (w.ends_at at time zone p.time_zone))::integer + 1440
      end as end_min
    from public.willing_windows w
    join public.plan_responses r on r.id = w.response_id
    join public.plans p on p.id = r.plan_id
    where r.id = any (p_response_ids) and r.status = 'windows'
  ),
  bands (part, band_start, band_end) as (
    values ('morning', 0, 720), ('afternoon', 720, 1020), ('evening', 1020, 1440)
  ),
  covered as (
    select parts.prefix || '_' || bands.part as daypart
    from parts
    join bands on parts.start_min < bands.band_end and parts.end_min > bands.band_start
  ),
  all_parts (daypart, ordinal) as (
    values ('weekday_morning', 1), ('weekday_afternoon', 2), ('weekday_evening', 3),
           ('weekend_morning', 4), ('weekend_afternoon', 5), ('weekend_evening', 6)
  )
  select jsonb_object_agg(a.daypart, coalesce(c.n, 0) order by a.ordinal)
  from all_parts a
  left join (select daypart, count(*)::integer as n from covered group by daypart) c on c.daypart = a.daypart;
$$;

comment on function jobs.daypart_counts(uuid[]) is
  'How many of the given responses'' windows cover each of the six dayparts, by dayPartsCovered()''s rule.';

revoke all on function jobs.daypart_counts(uuid[]) from public;
revoke all on function jobs.daypart_counts(uuid[]) from anon, authenticated;

-- supabase/sql/functions/jobs/daypart_summary.sql
-- `summariseDayparts()`'s shape from a set of counts: the parts most offered
-- first, ties in the fixed order.

create or replace function jobs.daypart_summary(p_counts jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  with all_parts (daypart, ordinal) as (
    values ('weekday_morning', 1), ('weekday_afternoon', 2), ('weekday_evening', 3),
           ('weekend_morning', 4), ('weekend_afternoon', 5), ('weekend_evening', 6)
  ),
  counted as (
    select a.daypart, a.ordinal, coalesce((p_counts ->> a.daypart)::integer, 0) as n
    from all_parts a
  )
  select jsonb_build_object(
    'parts', coalesce((select jsonb_agg(daypart order by n desc, ordinal) from counted where n > 0), '[]'::jsonb),
    'counts', (select jsonb_object_agg(daypart, n order by ordinal) from counted)
  );
$$;

comment on function jobs.daypart_summary(jsonb) is
  'The stored shape — {parts, counts} — from a set of counts, as summariseDayparts() orders them.';

revoke all on function jobs.daypart_summary(jsonb) from public;
revoke all on function jobs.daypart_summary(jsonb) from anon, authenticated;

-- supabase/sql/functions/jobs/emit.sql
-- The one way in. Definer, so that a trigger firing as a member can append
-- without the member holding anything in `jobs`; callable by the service
-- role, so an Edge Function can announce what it did (invite rotated,
-- contact verified, nudge shown) without a table grant.

create or replace function jobs.emit(
  p_event_name text,
  p_aggregate_type text,
  p_aggregate_id uuid,
  p_payload jsonb default '{}'::jsonb
)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into jobs.outbox (event_name, aggregate_type, aggregate_id, payload)
  values (p_event_name, p_aggregate_type, p_aggregate_id, coalesce(p_payload, '{}'::jsonb))
  returning id;
$$;

comment on function jobs.emit(text, text, uuid, jsonb) is
  'Appends one domain event to the outbox. Every definer function and the service role write events through this; nothing else inserts into jobs.outbox.';

revoke all on function jobs.emit(text, text, uuid, jsonb) from public;
revoke all on function jobs.emit(text, text, uuid, jsonb) from anon, authenticated;
grant execute on function jobs.emit(text, text, uuid, jsonb) to service_role;

-- supabase/sql/functions/jobs/invoke_process_scheduled_jobs.sql
-- ---------------------------------------------------------------------------
-- The schedule.
--
-- The minute job calls the Edge Function through pg_net. The URL and the
-- bearer are database settings — `circles.functions_url`,
-- `circles.cron_secret` — set per environment after deploy and never written
-- in a migration. Until they are set the job is a no-op, so a fresh local
-- stack does not log a failed HTTP call every minute. The call is wrapped in
-- a function so the job's command text, which anyone who can read `cron.job`
-- can read, does not contain the header expression.
-- ---------------------------------------------------------------------------

create or replace function jobs.invoke_process_scheduled_jobs()
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  base_url text := nullif(current_setting('circles.functions_url', true), '');
  secret text := nullif(current_setting('circles.cron_secret', true), '');
begin
  if base_url is null or secret is null then
    return null;
  end if;
  return net.http_post(
    url := base_url || '/process-scheduled-jobs',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 55000
  );
end;
$$;

comment on function jobs.invoke_process_scheduled_jobs() is
  'Asks process-scheduled-jobs to run, via pg_net, with the bearer from circles.cron_secret. Null and no call when the settings are absent.';

revoke all on function jobs.invoke_process_scheduled_jobs() from public;
revoke all on function jobs.invoke_process_scheduled_jobs() from anon, authenticated;
revoke all on function jobs.invoke_process_scheduled_jobs() from service_role;

-- supabase/sql/functions/jobs/on_attendance_updated.sql
-- A status somebody chose. On update, one that changed: the `before` trigger
-- in 0005 turns a repeat into a no-op by returning the old row, but the
-- `after` trigger still fires, so the comparison is made again here. On
-- insert, one the member wrote themselves — a participant with no derived
-- row yet answering for the first time — which is `auth.uid()` being the row's
-- user and `transition_plan` not being in the middle of deriving; the rows it
-- derives at confirmation are not "updates" anybody made.

create or replace function jobs.on_attendance_updated()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  plan_id uuid;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;
  if tg_op = 'INSERT' and (
    new.user_id is distinct from auth.uid()
    or coalesce(current_setting('circles.deriving_attendance', true), '') = 'on'
  ) then
    return new;
  end if;
  select c.plan_id into plan_id from public.meetup_confirmations c where c.id = new.confirmation_id;
  perform jobs.emit('confirmation.attendance_updated', 'confirmation', new.confirmation_id, jsonb_build_object(
    'confirmation_id', new.confirmation_id,
    'plan_id', plan_id,
    'user_id', new.user_id,
    'status', new.status
  ));
  return new;
end;
$$;

revoke all on function jobs.on_attendance_updated() from public;
revoke all on function jobs.on_attendance_updated() from anon, authenticated;

-- supabase/sql/functions/jobs/on_circle_created.sql
-- ---------------------------------------------------------------------------
-- Paying the debt: the events owed since S1-07.
--
-- Two kinds of writer. A *fact about a row* — a circle exists, a member
-- joined or was removed, an answer was given, an attendance changed — is
-- announced by a trigger on the row, so every writer announces it: the
-- function that exists today, the Edge Function that inserts as the service
-- role tomorrow, and the one nobody has written yet. A *transition* is
-- announced by `transition_plan`, because only it knows which action was
-- taken — the row diff of `collecting → collecting` cannot tell an `edit`
-- from an `accept_organiser`, and deriving the action from the shape it left
-- behind is the guard-checks-the-form mistake with an event name on it.
--
-- The trigger functions are definer: a member who inserts their own
-- attendance holds nothing in `jobs`, and must not need to.
-- ---------------------------------------------------------------------------

create or replace function jobs.on_circle_created()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform jobs.emit('circles.circle_created', 'circle', new.id, jsonb_build_object(
    'circle_id', new.id,
    'owner_user_id', new.owner_user_id,
    'cadence', new.cadence,
    'time_zone', new.time_zone
  ));
  return new;
end;
$$;

revoke all on function jobs.on_circle_created() from public;
revoke all on function jobs.on_circle_created() from anon, authenticated;

-- supabase/sql/functions/jobs/on_member_changed.sql
create or replace function jobs.on_member_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform jobs.emit('circles.member_joined', 'circle', new.circle_id, jsonb_build_object(
      'circle_id', new.circle_id,
      'user_id', new.user_id,
      'role', new.role
    ));
  elsif new.status = 'removed' and old.status <> 'removed' then
    perform jobs.emit('circles.member_removed', 'circle', new.circle_id, jsonb_build_object(
      'circle_id', new.circle_id,
      'user_id', new.user_id
    ));
  end if;
  return new;
end;
$$;

revoke all on function jobs.on_member_changed() from public;
revoke all on function jobs.on_member_changed() from anon, authenticated;

-- supabase/sql/functions/jobs/on_nudge_changed.sql
-- A client writes this table directly (§8.4) and cannot emit, so the row
-- announces itself: shown on insert, answered when the answer changes.

create or replace function jobs.on_nudge_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform jobs.emit('growth.nudge_shown', 'nudge', new.id, jsonb_build_object(
      'nudge_id', new.id, 'user_id', new.user_id, 'moment', new.moment, 'plan_id', new.plan_id
    ));
    if new.answer is not null then
      perform jobs.emit('growth.nudge_answered', 'nudge', new.id, jsonb_build_object(
        'nudge_id', new.id, 'user_id', new.user_id, 'moment', new.moment, 'plan_id', new.plan_id,
        'answer', new.answer
      ));
    end if;
  elsif new.answer is distinct from old.answer and new.answer is not null then
    perform jobs.emit('growth.nudge_answered', 'nudge', new.id, jsonb_build_object(
      'nudge_id', new.id, 'user_id', new.user_id, 'moment', new.moment, 'plan_id', new.plan_id,
      'answer', new.answer
    ));
  end if;
  return new;
end;
$$;

revoke all on function jobs.on_nudge_changed() from public;
revoke all on function jobs.on_nudge_changed() from anon, authenticated;

-- supabase/sql/functions/jobs/on_response_changed.sql
-- One row per answer: `replace_response` upserts the response row exactly
-- once per call (0004), so this is one event per answer, not one per window.
-- A deleted answer is a cleared one — removal deletes them (§4.5) — unless
-- the plan itself is going, in which case there is nobody left to tell.

create or replace function jobs.on_response_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    if exists (select 1 from public.plans p where p.id = old.plan_id) then
      perform jobs.emit('availability.response_cleared', 'plan', old.plan_id, jsonb_build_object(
        'plan_id', old.plan_id,
        'revision', old.revision,
        'user_id', old.user_id
      ));
    end if;
    return old;
  end if;
  perform jobs.emit('availability.response_submitted', 'plan', new.plan_id, jsonb_build_object(
    'plan_id', new.plan_id,
    'revision', new.revision,
    'user_id', new.user_id,
    'status', new.status,
    'used_calendar_overlay', new.used_calendar_overlay
  ));
  return new;
end;
$$;

revoke all on function jobs.on_response_changed() from public;
revoke all on function jobs.on_response_changed() from anon, authenticated;

-- supabase/sql/functions/jobs/release_lease.sql
create or replace function jobs.release_lease(p_name text, p_holder text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  released boolean;
begin
  -- Only the holder releases. A late finisher whose lease has already been
  -- taken over must not release the new holder's.
  update jobs.cron_leases l
  set leased_until = null, last_finished_at = now()
  where l.name = p_name and l.holder = p_holder and l.leased_until is not null
  returning true into released;
  return coalesce(released, false);
end;
$$;

comment on function jobs.release_lease(text, text) is
  'Releases the named lease if the caller holds it. False otherwise — a lease that lapsed and was taken by another holder stays theirs.';

revoke all on function jobs.release_lease(text, text) from public;
revoke all on function jobs.release_lease(text, text) from anon, authenticated;
grant execute on function jobs.release_lease(text, text) to service_role;

-- supabase/sql/functions/jobs/run_retention.sql
-- ---------------------------------------------------------------------------
-- Retention (§8.5, ADR 0005).
--
-- One function, one rule per statement, each returning what it deleted so the
-- run can be read afterwards. Runs as the owner: the service role holds no
-- delete on the two logs and cannot touch `auth.users`, and that is right —
-- an Edge Function with the power to purge is a bigger surface than a cron
-- job in the database.
--
-- Things this deliberately does not delete:
--   * suppressed contacts — the suppression list is the promise not to send
--     again, and it has to outlive the address it is about;
--   * analytics events — the record;
--   * plans, responses, confirmations — the product's history.
-- ---------------------------------------------------------------------------

create or replace function jobs.run_retention()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  n_outbox integer;
  n_jobs integer;
  n_delivery integer;
  n_invites integer;
  n_tokens integer;
  n_pending_contacts integer;
  n_plan_contacts integer;
  n_summaries integer;
  n_summaries_purged integer;
  n_windows_aged integer;
  n_windows_gone integer;
  n_anonymous integer;
  n_audit integer;
  result jsonb;
begin
  -- Outbox and pipeline bookkeeping: 30 days. An unprocessed outbox row is
  -- never deleted, however old — the health job reports it instead.
  delete from jobs.outbox where processed_at < now() - interval '30 days';
  get diagnostics n_outbox = row_count;

  delete from jobs.notification_jobs where created_at < now() - interval '30 days';
  get diagnostics n_jobs = row_count;

  delete from private.email_delivery_events where recorded_at < now() - interval '30 days';
  get diagnostics n_delivery = row_count;

  -- Revoked invite hashes: 30 days.
  delete from public.circle_invites where revoked_at < now() - interval '30 days';
  get diagnostics n_invites = row_count;

  -- Expired or used tokens: 7 days after they stopped being usable.
  delete from private.email_action_tokens
  where expires_at < now() - interval '7 days'
     or used_at < now() - interval '7 days';
  get diagnostics n_tokens = row_count;

  -- Unverified contacts: 7 days. Somebody typed an address and never clicked
  -- the link; the address does not stay — unless a link they could still
  -- click exists, because a contact that asked for a fresh link yesterday is
  -- not one that gave up a week ago, and the cascade would take the link.
  delete from private.email_contacts c
  where c.status = 'pending'
    and c.created_at < now() - interval '7 days'
    and not exists (
      select 1 from private.email_action_tokens t
      where t.contact_id = c.id and t.used_at is null and t.expires_at > now()
    );
  get diagnostics n_pending_contacts = row_count;

  -- Verified plan-only contacts: 30 days after every plan they were subscribed
  -- to has finished. Every contact in the MVP is plan-only (spec §3: no
  -- marketing consent), so "plan-only" means "verified and not suppressed".
  -- A contact with a live subscription stays; one whose plans have all been
  -- completed, cancelled or expired for 30 days goes, address and all. A
  -- withdrawn subscription keeps nothing: the person said stop, and the
  -- address has no reason left to be here.
  delete from private.email_contacts c
  where c.status = 'verified'
    and not exists (
      select 1
      from private.email_subscriptions s
      join public.plans p on p.id = s.plan_id
      where s.contact_id = c.id
        and s.status = 'active'
        and (p.state not in ('completed', 'cancelled', 'expired')
             or p.updated_at > now() - interval '30 days')
    )
    and c.verified_at < now() - interval '30 days';
  get diagnostics n_plan_contacts = row_count;

  -- Willing windows, rule one (ADR 0005): 12 months, for members of active
  -- circles — after the summary is written, from everything still stored,
  -- so that what the member usually offers survives the windows going.
  -- Dropped first: two runs in one transaction (a test, a retry) would
  -- otherwise meet their own table.
  perform set_config('client_min_messages', 'warning', true);
  drop table if exists aged_responses;
  create temporary table aged_responses on commit drop as
    select r.id as response_id, p.circle_id, r.user_id
    from public.plan_responses r
    join public.plans p on p.id = r.plan_id
    join public.circles c on c.id = p.circle_id
    join public.circle_members m on m.circle_id = c.id and m.user_id = r.user_id
    where r.submitted_at < now() - interval '12 months'
      and c.status = 'active'
      and m.status = 'active'
      and exists (select 1 from public.willing_windows w where w.response_id = r.id);

  -- Added to what is already summarised, never recomputed from what is left:
  -- the windows that went last time are in the stored counts and nowhere else.
  insert into public.member_dayparts (circle_id, user_id, summary, computed_at)
  select g.circle_id, g.user_id,
    jobs.daypart_summary(jobs.add_daypart_counts(
      coalesce((select d.summary -> 'counts' from public.member_dayparts d
                where d.circle_id = g.circle_id and d.user_id = g.user_id), '{}'::jsonb),
      jobs.daypart_counts(g.response_ids)
    )),
    now()
  from (
    select a.circle_id, a.user_id, array_agg(a.response_id) as response_ids
    from aged_responses a group by a.circle_id, a.user_id
  ) g
  on conflict (circle_id, user_id) do update
    set summary = excluded.summary, computed_at = excluded.computed_at;
  get diagnostics n_summaries = row_count;

  delete from public.willing_windows w
  using aged_responses a
  where w.response_id = a.response_id;
  get diagnostics n_windows_aged = row_count;

  -- Willing windows, rule two: 30 days after removal or archiving. No summary
  -- — a removed member's pre-fill is nobody's to keep — and the summary that
  -- was written while they were a member goes with the windows.
  delete from public.member_dayparts d
  using public.circle_members m, public.circles c
  where m.circle_id = d.circle_id and m.user_id = d.user_id
    and c.id = d.circle_id
    and (
      (m.status = 'removed' and m.updated_at < now() - interval '30 days')
      or (c.status = 'archived' and c.updated_at < now() - interval '30 days')
    );
  get diagnostics n_summaries_purged = row_count;

  delete from public.willing_windows w
  using public.plan_responses r, public.plans p, public.circles c, public.circle_members m
  where w.response_id = r.id
    and p.id = r.plan_id
    and c.id = p.circle_id
    and m.circle_id = c.id and m.user_id = r.user_id
    and (
      (m.status = 'removed' and m.updated_at < now() - interval '30 days')
      or (c.status = 'archived' and c.updated_at < now() - interval '30 days')
    );
  get diagnostics n_windows_gone = row_count;

  -- Abandoned anonymous identities: a guest session that never joined
  -- anything, 30 days on. The cascade takes the profile.
  delete from auth.users u
  where coalesce(u.is_anonymous, false)
    and u.created_at < now() - interval '30 days'
    and not exists (select 1 from public.circle_members m where m.user_id = u.id);
  get diagnostics n_anonymous = row_count;

  -- Audit log: 12 months.
  delete from private.audit_log where occurred_at < now() - interval '12 months';
  get diagnostics n_audit = row_count;

  result := jsonb_build_object(
    'outbox', n_outbox,
    'notification_jobs', n_jobs,
    'delivery_events', n_delivery,
    'revoked_invites', n_invites,
    -- Not "tokens": the key would trip the no-content check that guards the
    -- audit log, and rightly — a count of links is what this is.
    'expired_action_links', n_tokens,
    'pending_contacts', n_pending_contacts,
    'plan_only_contacts', n_plan_contacts,
    'daypart_summaries', n_summaries,
    'daypart_summaries_purged', n_summaries_purged,
    'windows_aged', n_windows_aged,
    'windows_of_the_gone', n_windows_gone,
    'anonymous_identities', n_anonymous,
    'audit_rows', n_audit
  );

  -- The run is itself a fact worth keeping for a year: counts only.
  insert into private.audit_log (action, resource_type, metadata)
  values ('retention.ran', 'account', result);

  return result;
end;
$$;

comment on function jobs.run_retention() is
  'The daily retention rules of §8.5 and ADR 0005, one statement each; returns what each deleted. Runs as the owner from pg_cron.';

revoke all on function jobs.run_retention() from public;
revoke all on function jobs.run_retention() from anon, authenticated;
revoke all on function jobs.run_retention() from service_role;

-- supabase/sql/functions/planning/allowed_keys.sql
-- The payload keys an action may carry. Anything else is refused, not ignored:
-- a caller that sends `quorum` with a `cancel` has misunderstood something,
-- and silently dropping it would let the misunderstanding ship.
--
-- `confirm` carries the confirmation's details as well as the candidate,
-- because `transition_plan` writes the confirmation row itself.

create or replace function planning.allowed_keys(action text)
returns text[]
language sql
immutable
as $$
  select case
    when action in ('edit', 'reopen') then array[
      'window_start', 'window_end', 'daily_start_local', 'daily_end_local',
      'duration_minutes', 'quorum', 'response_deadline'
    ]
    when action = 'cancel' then array['cancel_note']
    when action = 'confirm' then array['candidate_id', 'place_name', 'place_url', 'note', 'chased_answer']
    else array[]::text[]
  end;
$$;

revoke all on function planning.allowed_keys(text) from public;
revoke all on function planning.allowed_keys(text) from anon, authenticated;

-- supabase/sql/functions/planning/candidate_is_eligible.sql
-- ---------------------------------------------------------------------------
-- The candidate guard: whether an id names a time still on offer.
--
-- The check is the domain's: the id names an eligible candidate in the set for
-- the plan's *current* revision, input version and scoring version — a
-- candidate can stop being eligible between the organiser opening the review
-- screen and tapping the button, and a set computed before somebody withdrew
-- a reply names people who are no longer free.
-- ---------------------------------------------------------------------------

create or replace function planning.candidate_is_eligible(plan public.plans, candidate_id text)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  start_at timestamptz;
begin
  -- The client's candidate id is the ISO start (candidateIdOf). Anything that
  -- is not an instant is not a candidate, rather than an error.
  begin
    start_at := candidate_id::timestamptz;
  exception when others then
    return false;
  end;

  return exists (
    select 1
    from public.candidate_sets cs
    join public.candidates c on c.candidate_set_id = cs.id
    where cs.plan_id = plan.id
      and cs.revision = plan.revision
      and cs.input_version = plan.input_version
      and cs.scoring_version = plan.scoring_version
      and not c.is_near_miss
      and c.starts_at = start_at
  );
end;
$$;

revoke all on function planning.candidate_is_eligible(public.plans, text) from public;
revoke all on function planning.candidate_is_eligible(public.plans, text) from anon, authenticated;

-- supabase/sql/functions/planning/event_for.sql
-- The transition → event map. Immutable and total over `planning.transitions`;
-- `075_outbox_events.sql` walks that table and fails if a row maps to null,
-- so a transition added by the generator cannot arrive silent.

create or replace function planning.event_for(p_from_state text, p_action text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_action
    when 'create_named' then 'planning.plan_created'
    when 'create_quiet' then 'planning.quiet_ask_created'
    when 'threshold_reached' then 'planning.threshold_reached'
    when 'expire' then 'planning.plan_expired'
    when 'accept_organiser' then 'planning.organiser_accepted'
    when 'edit' then 'planning.plan_revised'
    when 'candidates_ready' then 'scheduling.candidates_generated'
    -- `candidates_gone` is the engine's bookkeeping: an answer moved, the set
    -- is stale, a recalculation follows. It says nothing about whether options
    -- exist, so it announces nothing — `scheduling.no_eligible_candidates` is
    -- the recalculation's to emit, from what it actually found (S1-16).
    when 'candidates_gone' then null
    when 'confirm' then 'confirmation.meetup_confirmed'
    when 'reopen' then 'confirmation.meetup_rescheduled'
    when 'report_outcome' then 'confirmation.outcome_reported'
    -- Cancelling a confirmed meetup is a different message from withdrawing
    -- an ask: "Thursday is off" goes to everyone who had it in a calendar.
    when 'cancel' then case p_from_state
      when 'confirmed' then 'confirmation.meetup_cancelled'
      else 'planning.plan_cancelled'
    end
    else null
  end;
$$;

comment on function planning.event_for(text, text) is
  'The outbox event a transition announces. Total over planning.transitions except the named silent bookkeeping actions, by test.';

revoke all on function planning.event_for(text, text) from public;
revoke all on function planning.event_for(text, text) from anon, authenticated;

-- supabase/sql/functions/planning/transition_plan.sql
-- transition_plan, redefined whole from 0004 with the emit in place of the
-- TODO. The body is otherwise byte-for-byte 0004's; the diff of this file
-- against that one is the review.

create or replace function planning.transition_plan(
  p_plan_id uuid,
  p_action text,
  p_actor uuid,
  p_payload jsonb default '{}'::jsonb
)
returns public.plans
language plpgsql
security definer
set search_path = ''
as $$
declare
  plan public.plans;
  rule planning.transitions;
  member public.circle_members;
  is_permanent boolean;
  guard text;
  next_revision integer;
  event_name text;
  event_payload jsonb;
  confirmation_id uuid;
begin
  select * into plan from public.plans where id = p_plan_id for update;
  if not found then
    raise exception 'PLAN_NOT_FOUND' using errcode = 'P0001';
  end if;

  select * into rule
  from planning.transitions t
  where t.from_state = plan.state and t.action = p_action;

  if not found then
    if plan.state in ('completed', 'expired', 'cancelled') then
      raise exception 'plan_is_finished' using errcode = 'P0001';
    end if;
    raise exception 'wrong_state' using errcode = 'P0001';
  end if;

  select * into member
  from public.circle_members m
  where m.circle_id = plan.circle_id and m.user_id = p_actor and m.status = 'active';

  select p.is_permanent into is_permanent
  from public.profiles p where p.user_id = p_actor;

  -- Shape before semantics, and this is a reorder from 0003: a caller who sent
  -- a key the action does not take should learn that first, rather than only
  -- after producing a candidate the guard accepts.
  if exists (
    select 1 from jsonb_object_keys(p_payload) k
    where k <> all (planning.allowed_keys(p_action))
  ) then
    raise exception 'unexpected_payload' using errcode = 'P0001';
  end if;

  foreach guard in array rule.guards loop
    case guard
      when 'member' then
        if member.user_id is null then
          raise exception 'not_a_member' using errcode = 'P0001';
        end if;
      when 'organiser' then
        if plan.organiser_user_id is distinct from p_actor or member.user_id is null then
          raise exception 'not_the_organiser' using errcode = 'P0001';
        end if;
      when 'permanent' then
        if not coalesce(is_permanent, false) then
          raise exception 'needs_permanent_identity' using errcode = 'P0001';
        end if;
      when 'no_organiser_yet' then
        if plan.organiser_user_id is not null then
          raise exception 'already_has_organiser' using errcode = 'P0001';
        end if;
      when 'initiator' then
        if not exists (
          select 1 from private.plan_initiators pi
          where pi.plan_id = plan.id and pi.initiator_user_id = p_actor
        ) then
          raise exception 'not_the_initiator' using errcode = 'P0001';
        end if;
      when 'keen_initiator_or_owner' then
        if not exists (
          select 1 from private.plan_interest i
          where i.plan_id = plan.id and i.user_id = p_actor and i.response = 'keen'
        ) and not exists (
          select 1 from private.plan_initiators pi
          where pi.plan_id = plan.id and pi.initiator_user_id = p_actor
        ) and not exists (
          select 1 from public.circles c
          where c.id = plan.circle_id and c.owner_user_id = p_actor
        ) then
          raise exception 'not_keen_initiator_or_owner' using errcode = 'P0001';
        end if;
      when 'threshold' then
        if plan.quiet_threshold is null or (
          select count(*) from private.plan_interest i
          where i.plan_id = plan.id and i.response = 'keen'
        ) < plan.quiet_threshold then
          raise exception 'threshold_not_reached' using errcode = 'P0001';
        end if;
      when 'candidate' then
        -- Eligibility, not presence. This is the line 0003 could not write.
        if not planning.candidate_is_eligible(plan, p_payload ->> 'candidate_id') then
          raise exception 'needs_candidate' using errcode = 'P0001';
        end if;
        -- `confirm()` in the domain: a candidate that begins in the past is
        -- removed on recalculation (spec §9), and confirming one in the
        -- meantime would lock in a time that has gone. Eligibility is about
        -- the set; this is about the clock, and it is checked here too.
        if (p_payload ->> 'candidate_id')::timestamptz <= now() then
          raise exception 'candidate_has_passed' using errcode = 'P0001';
        end if;
      else
        raise exception 'UNKNOWN_GUARD_%', guard using errcode = 'P0001';
    end case;
  end loop;

  next_revision := plan.revision + (case when rule.bumps_revision then 1 else 0 end);

  perform set_config('circles.in_transition', 'on', true);

  update public.plans p set
    state = rule.to_state,
    revision = next_revision,
    input_version = case when rule.bumps_revision then 1 else p.input_version end,
    organiser_user_id = case
      when p_action = 'accept_organiser' then p_actor
      else p.organiser_user_id
    end,
    window_start = coalesce((p_payload ->> 'window_start')::date, p.window_start),
    window_end = coalesce((p_payload ->> 'window_end')::date, p.window_end),
    daily_start_local = coalesce((p_payload ->> 'daily_start_local')::integer, p.daily_start_local),
    daily_end_local = coalesce((p_payload ->> 'daily_end_local')::integer, p.daily_end_local),
    duration_minutes = coalesce((p_payload ->> 'duration_minutes')::integer, p.duration_minutes),
    quorum = coalesce((p_payload ->> 'quorum')::integer, p.quorum),
    response_deadline = coalesce((p_payload ->> 'response_deadline')::timestamptz, p.response_deadline),
    cancel_note = case
      when rule.to_state = 'cancelled' then p_payload ->> 'cancel_note'
      else p.cancel_note
    end
  where p.id = p_plan_id
  returning * into plan;

  perform set_config('circles.in_transition', 'off', true);

  -- `confirm` is not a state change with a row to follow; it is the row. The
  -- frozen copy of the candidate and the derived attendance are written here,
  -- in the transaction that moves the plan and announces it, so that there is
  -- no moment at which a plan is `confirmed` with nothing confirmed — and no
  -- event about a confirmation that a later insert might fail to create. The
  -- candidate was proven eligible by the guard above; this reads the same row.
  if p_action = 'confirm' then
    insert into public.meetup_confirmations (
      plan_id, revision, candidate_id, starts_at, ends_at, available_user_ids,
      place_name, place_url, note, chased_answer, confirmed_by
    )
    select plan.id, plan.revision, p_payload ->> 'candidate_id', c.starts_at, c.ends_at, c.available_user_ids,
      p_payload ->> 'place_name', p_payload ->> 'place_url', p_payload ->> 'note', p_payload ->> 'chased_answer',
      p_actor
    from public.candidate_sets cs
    join public.candidates c on c.candidate_set_id = cs.id
    where cs.plan_id = plan.id
      and cs.revision = plan.revision
      and cs.input_version = plan.input_version
      and cs.scoring_version = plan.scoring_version
      and not c.is_near_miss
      and c.starts_at = (p_payload ->> 'candidate_id')::timestamptz
    returning id into confirmation_id;

    -- `deriveAttendance`: `going` for anyone frozen in as available, `cant` for
    -- anyone who answered this revision and is not, `unknown` for anyone who
    -- never answered. Derived, not said — the marker keeps the attendance
    -- trigger from announcing the organiser's own row as a fresh answer.
    perform set_config('circles.deriving_attendance', 'on', true);
    insert into public.attendance (confirmation_id, user_id, status)
    select confirmation_id, pp.user_id,
      case
        when pp.user_id = any (c.available_user_ids) then 'going'
        when exists (
          select 1 from public.plan_responses r
          where r.plan_id = plan.id and r.revision = plan.revision and r.user_id = pp.user_id
        ) then 'cant'
        else 'unknown'
      end
    from public.plan_participants pp
    cross join (select available_user_ids from public.meetup_confirmations where id = confirmation_id) c
    where pp.plan_id = plan.id and pp.revision = plan.revision;
    perform set_config('circles.deriving_attendance', 'off', true);
  end if;

  -- The event, in the same transaction as the change (ADR 0003). Its name
  -- comes from the transition, not from the caller, and a transition without
  -- a name is refused rather than silently unannounced — `075_outbox_events`
  -- walks the table so a new row cannot arrive without one. The one silence is
  -- named here and there: `candidates_gone`, see `event_for`.
  event_name := planning.event_for(rule.from_state, p_action);
  if event_name is null and p_action not in ('candidates_gone') then
    raise exception 'no outbox event for transition % / %', rule.from_state, p_action
      using errcode = 'P0001';
  end if;

  -- What the payload may say. The actor is never named as such: on a quiet ask
  -- the actor of `create_quiet` and of `cancel` is the initiator, whose
  -- identity is the one thing the row must never say (§14). The organiser is a
  -- public fact and is carried once accepted; a threshold event carries the
  -- plan and the keen count only (§6.3).
  event_payload := jsonb_build_object(
    'plan_id', plan.id,
    'circle_id', plan.circle_id,
    'mode', plan.mode,
    'action', p_action,
    'from_state', rule.from_state,
    'to_state', plan.state,
    'revision', plan.revision
  );
  if plan.organiser_user_id is not null then
    event_payload := event_payload || jsonb_build_object('organiser_user_id', plan.organiser_user_id);
  end if;
  if p_action = 'threshold_reached' then
    event_payload := event_payload || jsonb_build_object('keen_count', (
      select count(*) from private.plan_interest i
      where i.plan_id = plan.id and i.response = 'keen'
    ));
  end if;
  if p_action = 'confirm' then
    event_payload := event_payload || jsonb_build_object('candidate_id', p_payload ->> 'candidate_id');
  end if;
  if event_name is not null then
    perform jobs.emit(event_name, 'plan', plan.id, event_payload);
  end if;


  return plan;
end;
$$;

revoke all on function planning.transition_plan(uuid, text, uuid, jsonb) from public;
revoke all on function planning.transition_plan(uuid, text, uuid, jsonb) from anon, authenticated;
grant execute on function planning.transition_plan(uuid, text, uuid, jsonb) to service_role;

-- supabase/sql/functions/private/apply_suppression.sql
create or replace function private.apply_suppression()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  tombstone private.email_suppressions;
begin
  select * into tombstone from private.email_suppressions t
  where t.email_hash = extensions.digest(new.email_normalized, 'sha256');
  if found then
    new.status := 'suppressed';
    new.suppression_reason := tombstone.reason;
    new.suppressed_at := tombstone.suppressed_at;
    new.verified_at := null;
  end if;
  return new;
end;
$$;

revoke all on function private.apply_suppression() from public;
revoke all on function private.apply_suppression() from anon, authenticated;

-- supabase/sql/functions/private/enforce_reentry_for_guests.sql
-- And the owner is a guest. A saved-place member signs in; a re-entry link
-- for them would be a sign-in bypass, so it is refused at issue rather than
-- trusted at consumption.

create or replace function private.enforce_reentry_for_guests()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.purpose = 'reentry' and exists (
    select 1 from public.profiles p
    where p.user_id = new.membership_user_id and p.is_permanent
  ) then
    raise exception 'reentry_token_for_permanent_identity' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

revoke all on function private.enforce_reentry_for_guests() from public;
revoke all on function private.enforce_reentry_for_guests() from anon, authenticated;

-- supabase/sql/functions/private/record_suppression.sql
create or replace function private.record_suppression()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'suppressed' and (tg_op = 'INSERT' or old.status is distinct from 'suppressed') then
    insert into private.email_suppressions (email_hash, reason, suppressed_at)
    values (new.email_hash, new.suppression_reason, new.suppressed_at)
    on conflict (email_hash) do nothing;
  end if;
  return null;
end;
$$;

revoke all on function private.record_suppression() from public;
revoke all on function private.record_suppression() from anon, authenticated;

-- supabase/sql/functions/public/apply_outcome.sql
-- ---------------------------------------------------------------------------
-- Outcomes.
--
-- Mirrors `reportOutcome` and `lastMetAtAfter`. One insert does four things,
-- in one transaction, so none can happen without the others: the plan moves
-- to `completed` through `transition_plan` (which is where "is this the
-- organiser, and still a member" is decided — not re-derived here), the
-- confirmation closes, and the circle's `last_met_at` moves if — and only if —
-- the answer was `happened`, and only forwards.
-- ---------------------------------------------------------------------------

create or replace function public.apply_outcome()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  confirmation public.meetup_confirmations;
  plan public.plans;
begin
  -- Lock order is plan, then confirmation — the same order `cancel` and
  -- `reopen` take (`transition_plan` locks the plan; its trigger then writes
  -- the confirmation). Locking the confirmation first here would let an
  -- outcome racing a cancel deadlock instead of one of them simply losing.
  -- The confirmation is read again after the lock, because the loser has to
  -- see what the winner did.
  select p.* into plan
  from public.plans p
  join public.meetup_confirmations c on c.plan_id = p.id
  where c.id = new.confirmation_id
  for update of p;
  select * into confirmation from public.meetup_confirmations c where c.id = new.confirmation_id;

  -- Reporting on a superseded confirmation would attach an outcome to a time
  -- that was replaced — and, through the `last_met_at` move below, could set
  -- the circle's record to an evening it explicitly abandoned.
  if confirmation.status <> 'active' then
    raise exception 'confirmation_not_active' using errcode = 'check_violation';
  end if;
  if confirmation.revision <> plan.revision then
    raise exception 'stale_confirmation' using errcode = 'check_violation';
  end if;

  -- "The morning after a confirmed meetup" (spec §5.10). Asked any earlier the
  -- question has no answer yet, and `happened` would set `last_met_at` to an
  -- instant that has not arrived — which cadence then reads.
  if now() < confirmation.ends_at then
    raise exception 'outcome_too_early' using errcode = 'check_violation';
  end if;

  -- `statusAfter`: `cancelled` is the one outcome that says the meetup did not
  -- take place at all; the other three describe a finished attempt. Closed
  -- before the transition, so the plans trigger finds nothing left to close.
  update public.meetup_confirmations c
  set status = case when new.outcome = 'cancelled' then 'cancelled' else 'completed' end,
      superseded_at = now(),
      superseded_reason = 'outcome'
  where c.id = confirmation.id;

  -- The organiser guard lives in the state machine and is not duplicated here.
  -- A non-organiser, or an organiser who has left the circle, is refused by
  -- `transition_plan` with the same code the client's `canTransition` uses —
  -- and the refusal rolls the close above back with it.
  perform planning.transition_plan(plan.id, 'report_outcome', new.reported_by);

  -- Only `happened`, to the time the circle actually met rather than to now —
  -- and never backwards. An outcome can be reported late, and a circle that has
  -- met again since must not be told it last met a fortnight ago because
  -- somebody finally answered an old email. Cadence is built on this field.
  if new.outcome = 'happened' then
    update public.circles c
    set last_met_at = greatest(coalesce(c.last_met_at, confirmation.starts_at), confirmation.starts_at)
    where c.id = plan.circle_id;
  end if;

  return new;
end;
$$;

comment on function public.apply_outcome() is
  'Mirrors reportOutcome() and lastMetAtAfter(): completes the plan through transition_plan, closes the confirmation, and moves last_met_at only for `happened`, only forwards.';

revoke all on function public.apply_outcome() from public;
revoke all on function public.apply_outcome() from anon, authenticated;

-- supabase/sql/functions/public/auth_is_member.sql
-- ---------------------------------------------------------------------------
-- The authorisation helpers.
--
-- Every one is `security definer` with an empty `search_path` and revoked from
-- `public` (§14). The empty search path is not decoration: a definer function
-- that resolves an unqualified name through the caller's path can be pointed at
-- a table the caller controls.
-- ---------------------------------------------------------------------------

create or replace function public.auth_is_member(circle_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.circle_members m
    where m.circle_id = auth_is_member.circle_id
      and m.user_id = (select auth.uid())
      and m.status = 'active'
  );
$$;

comment on function public.auth_is_member(uuid) is
  'True when the caller is an active member of the circle. The select policy on every circle-scoped table in the product.';

revoke all on function public.auth_is_member(uuid) from public;
revoke all on function public.auth_is_member(uuid) from anon, authenticated;
grant execute on function public.auth_is_member(uuid) to anon, authenticated;

-- supabase/sql/functions/public/auth_is_owner.sql
create or replace function public.auth_is_owner(circle_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.circles c
    join public.circle_members m
      on m.circle_id = c.id
     and m.user_id = c.owner_user_id
     and m.status = 'active'
    where c.id = auth_is_owner.circle_id
      and c.owner_user_id = (select auth.uid())
  );
$$;

comment on function public.auth_is_owner(uuid) is
  'True when the caller owns the circle and is still an active member of it. An owner who left owns nothing.';

revoke all on function public.auth_is_owner(uuid) from public;
revoke all on function public.auth_is_owner(uuid) from anon, authenticated;
grant execute on function public.auth_is_owner(uuid) to anon, authenticated;

-- supabase/sql/functions/public/auth_is_permanent.sql
create or replace function public.auth_is_permanent()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  -- Signed in, and not anonymous. Read from the JWT rather than from
  -- `profiles`, because a row the caller can update is not a credential.
  --
  -- A missing claim reads as anonymous. That is the safe direction: the only
  -- thing this gates is creation, and refusing a permanent user is a retry
  -- while admitting an anonymous one strands a plan (ADR 0004).
  select (select auth.uid()) is not null
     and coalesce(
           nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'is_anonymous',
           'true'
         ) = 'false';
$$;

comment on function public.auth_is_permanent() is
  'True when the caller has a saved place (Apple, Google or email code). Gates circle and plan creation (ADR 0004). A missing claim reads as anonymous.';

revoke all on function public.auth_is_permanent() from public;
revoke all on function public.auth_is_permanent() from anon, authenticated;
grant execute on function public.auth_is_permanent() to anon, authenticated;

-- supabase/sql/functions/public/bump_input_version.sql
-- Statement-level, over transition tables, and suppressed inside
-- `replace_response`, which bumps exactly once itself. The first version was
-- row-level: replacing two windows with two others bumped five times, and the
-- version came to depend on how many windows a person painted — the per-row
-- behaviour ADR 0013 exists to rule out. The trigger is still here for every
-- other write path (a retention job, a migration), bumping once per statement.

create or replace function public.bump_input_version()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(current_setting('circles.in_replace_response', true), '') = 'on' then
    return null;
  end if;

  if tg_table_name = 'plan_responses' then
    update public.plans p
    set input_version = p.input_version + 1
    where (p.id, p.revision) in (
      select r.plan_id, r.revision from changed r
    );
  else
    update public.plans p
    set input_version = p.input_version + 1
    where (p.id, p.revision) in (
      select r.plan_id, r.revision
      from changed w
      join public.plan_responses r on r.id = w.response_id
    );
  end if;
  return null;
end;
$$;

revoke all on function public.bump_input_version() from public;
revoke all on function public.bump_input_version() from anon, authenticated;

-- supabase/sql/functions/public/canonical_display_name.sql
-- ---------------------------------------------------------------------------
-- What makes two names the same name.
--
-- This is `comparable()` from `packages/domain/src/circles/display-name.ts`,
-- rewritten in SQL because the index has to agree with it. Two implementations
-- of one rule is one rule that disagrees with itself, and here the disagreement
-- is silent: the domain refuses a name the database has already accepted, and
-- the roster shows two people called Zoe.
--
-- Collapse whitespace, trim, decompose, drop the diacritics, lowercase. Case is
-- preserved in what is *stored* — people write their own names — and ignored in
-- what is *compared*.
-- ---------------------------------------------------------------------------

create or replace function public.canonical_display_name(value text)
returns text
language sql
immutable
as $$
  select lower(
    regexp_replace(
      -- NFD splits "ë" into "e" plus a combining diaeresis; the range is the
      -- combining marks block, which the next step removes.
      normalize(
        btrim(regexp_replace(value, E'[\\s\u00a0\u1680\u2000-\u200b\u2028\u2029\u202f\u205f\u3000]+', ' ', 'g')),
        NFD
      ),
      -- The same enumerated class as `COMBINING_MARKS` in the domain's
      -- `display-name.ts`. Enumerated rather than a Unicode property escape
      -- because Postgres has none, and the two engines have to state one rule
      -- identically or the index stores a name the domain then refuses:
      -- Latin, Cyrillic, Hebrew points, Arabic harakat, Syriac, Thaana, and
      -- the three later combining blocks.
      E'[\u0300-\u036f\u0483-\u0489\u0591-\u05c7\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed\u0711\u0730-\u074a\u07a6-\u07b0\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20f0\ufe20-\ufe2f]', '', 'g'
    )
  );
$$;

comment on function public.canonical_display_name(text) is
  'The form two display names are compared in. Mirrors comparable() in packages/domain/src/circles/display-name.ts; the unique index depends on it.';

revoke all on function public.canonical_display_name(text) from public;
grant execute on function public.canonical_display_name(text) to anon, authenticated;

-- supabase/sql/functions/public/create_circle.sql
-- ---------------------------------------------------------------------------
-- create_circle
--
-- The only way a circle comes into existence. A definer function rather than an
-- insert policy, because a circle and its owner's membership have to appear
-- together — an insert policy would leave a window in which a circle exists
-- with no members and therefore no one who can see it.
-- ---------------------------------------------------------------------------

create or replace function public.create_circle(
  name text,
  color text,
  time_zone text,
  -- Required, and therefore ahead of the optional cadence. §9.1 has every
  -- mutation idempotent on a client-supplied key, and an optional one is a key
  -- nobody sends: the retry it guards against is the one where the client never
  -- saw a response and cannot tell a timeout from a failure.
  idempotency_key text,
  cadence text default 'none'
)
returns public.circles
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- The `ShortCode` contract's alphabet (`packages/contracts/src/ids.ts`).
  alphabet constant text := 'abcdefghjkmnpqrstuvwxyz23456789';
  caller uuid := (select auth.uid());
  caller_name text;
  created public.circles;
  code text;
  i integer;
begin
  if not public.auth_is_permanent() then
    -- The organiser gate (ADR 0004). Worded as a practical need by the client;
    -- here it is simply a refusal.
    raise exception 'creating a circle needs a saved place'
      using errcode = 'insufficient_privilege';
  end if;

  if coalesce(btrim(create_circle.idempotency_key), '') = '' then
    raise exception 'create_circle needs an idempotency key'
      using errcode = 'null_value_not_allowed';
  end if;

  -- A retry returns what the first attempt made. Creating a circle is the one
  -- mutation where a lost response is expensive: the client cannot tell a
  -- timeout from a failure, and trying again would leave the person with two
  -- circles and no way to tell which one they gave the link out for.
  select * into created
  from public.circles c
  where c.owner_user_id = caller and c.creation_key = create_circle.idempotency_key;
  if found then
    return created;
  end if;

  select p.display_name into caller_name from public.profiles p where p.user_id = caller;
  if caller_name is null then
    raise exception 'no profile for %', caller using errcode = 'foreign_key_violation';
  end if;

  -- Ten characters from the `ShortCode` alphabet — no `0`/`o`, no `1`/`l`/`i`,
  -- because a short code is read aloud and retyped. Not a secret and not
  -- required to be unguessable: the invite secret is the capability, and it
  -- never reaches a server (§14). The loop retries on collision rather than
  -- hoping there is none.
  loop
    code := '';
    for i in 1..10 loop
      code := code || substr(
        alphabet,
        1 + (get_byte(extensions.gen_random_bytes(1), 0) % length(alphabet)),
        1
      );
    end loop;
    exit when not exists (select 1 from public.circles c where c.short_code = code);
  end loop;

  insert into public.circles
    (owner_user_id, name, color, time_zone, cadence, short_code, creation_key)
  values (caller, create_circle.name, create_circle.color, create_circle.time_zone,
          create_circle.cadence, code, create_circle.idempotency_key)
  returning * into created;

  insert into public.circle_members (circle_id, user_id, display_name_snapshot, role)
  values (created.id, caller, caller_name, 'owner');

  -- `circles.circle_created` and `circles.member_joined` are written to
  -- `jobs.outbox` by the row triggers in 0006, in this transaction — on the
  -- rows rather than here, so that every writer of a circle or a membership
  -- announces it, not only this function.

  return created;

exception
  when unique_violation then
    -- Two identical requests in flight at once: the index caught the second, and
    -- the row the first one wrote is the answer.
    select * into created
    from public.circles c
    where c.owner_user_id = caller and c.creation_key = create_circle.idempotency_key;
    if found then
      return created;
    end if;
    raise;
end;
$$;

comment on function public.create_circle(text, text, text, text, text) is
  'Creates a circle and its owner membership in one transaction. Requires a permanent identity (ADR 0004).';

revoke all on function public.create_circle(text, text, text, text, text) from public;
revoke all on function public.create_circle(text, text, text, text, text) from anon, authenticated;
grant execute on function public.create_circle(text, text, text, text, text) to authenticated;

-- supabase/sql/functions/public/enforce_attendance_transition.sql
-- ---------------------------------------------------------------------------
-- Attendance transitions.
--
-- Mirrors `updateAttendance` / `applyAttendance` in the domain, rule for rule:
--
--   * before the meetup, `going` and `cant` swap freely; after it, `was_there`
--     and `missed` swap freely; nothing goes back from an answer about the
--     past to a promise about the future;
--   * a retrospective status is refused before the meetup has ended — "I was
--     there" before Thursday is not an early answer, it is a false one, and
--     `corroboration` would go on to count it;
--   * the same status twice is a no-op, not a fresh answer: the confirmed
--     screen orders by `updated_at`, and a duplicate tap must not announce a
--     change of mind nobody made;
--   * only a participant of the confirmation's revision has a row, and only on
--     a confirmation that is active or completed.
-- ---------------------------------------------------------------------------

create or replace function public.enforce_attendance_transition()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  confirmation public.meetup_confirmations;
  allowed text[];
begin
  select * into confirmation from public.meetup_confirmations c where c.id = new.confirmation_id;

  if confirmation.id is null then
    raise exception 'attendance_confirmation_missing' using errcode = 'foreign_key_violation';
  end if;
  if confirmation.status not in ('active', 'completed') then
    raise exception 'attendance_confirmation_not_live' using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.plan_participants pp
    where pp.plan_id = confirmation.plan_id
      and pp.revision = confirmation.revision
      and pp.user_id = new.user_id
  ) then
    raise exception 'attendance_not_a_participant' using errcode = 'check_violation';
  end if;

  if new.status in ('was_there', 'missed') and now() < confirmation.ends_at then
    raise exception 'attendance_too_early' using errcode = 'check_violation';
  end if;

  if tg_op = 'UPDATE' then
    if new.status = old.status then
      -- Idempotent: return the old row untouched, `updated_at` included.
      return old;
    end if;

    allowed := case old.status
      when 'unknown' then array['going', 'cant', 'was_there', 'missed']
      when 'going' then array['cant', 'was_there', 'missed']
      when 'cant' then array['going', 'was_there', 'missed']
      when 'was_there' then array['missed']
      when 'missed' then array['was_there']
    end;
    if not (new.status = any (allowed)) then
      raise exception 'attendance_not_reversible' using errcode = 'check_violation';
    end if;

    new.updated_at := now();
  end if;

  return new;
end;
$$;

comment on function public.enforce_attendance_transition() is
  'The attendance state machine, as updateAttendance() has it: no promise about the future after an answer about the past, no answer about the past before the meetup has ended, and a repeat is a no-op.';

revoke all on function public.enforce_attendance_transition() from public;
revoke all on function public.enforce_attendance_transition() from anon, authenticated;

-- supabase/sql/functions/public/enforce_confirmed_has_confirmation.sql
-- The backstop, at commit: a plan that is `confirmed` has an active
-- confirmation for its revision. `transition_plan` makes this true by
-- construction; this makes it impossible to be false by any other route.

create or replace function public.enforce_confirmed_has_confirmation()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  current public.plans;
begin
  -- Deferred to commit, so `new` is the row as it was when the update
  -- happened, not as it is now. A plan confirmed and then completed in one
  -- transaction (a seed, an outcome reported in the same call) has a
  -- confirmation that is `completed`, not `active`, and that is correct — the
  -- invariant is about the plan as it will be committed.
  select * into current from public.plans p where p.id = new.id;
  if current.state = 'confirmed' and not exists (
    select 1 from public.meetup_confirmations c
    where c.plan_id = current.id and c.revision = current.revision and c.status = 'active'
  ) then
    raise exception 'confirmed_without_confirmation' using errcode = 'check_violation';
  end if;
  return null;
end;
$$;

revoke all on function public.enforce_confirmed_has_confirmation() from public;
revoke all on function public.enforce_confirmed_has_confirmation() from anon, authenticated;

-- supabase/sql/functions/public/enforce_iana_zone.sql
-- `pg_timezone_names` and `Intl.DateTimeFormat` are not the same set, in both
-- directions, and the client validates with `Intl` (`packages/contracts/src/time.ts`):
--
--   * Postgres accepts `Factory` and the whole `posix/…` and `right/…` families,
--     which `Intl` refuses. Storing one means every member of that circle gets
--     a crash where a time should be.
--   * `Intl` accepts `australia/melbourne`; an exact-match lookup here refuses
--     it, so a contract-valid zone would be rejected at the database.
--
-- So: match case-insensitively, refuse the compatibility families, and store
-- the canonical spelling. `010_circles.sql` asserts that those families are the
-- *only* disagreement in this tzdata, so a future one is a failing test rather
-- than a surprise.

create or replace function public.enforce_iana_zone()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  supplied text := row_to_json(new) ->> tg_argv[0];
  canonical text;
begin
  select z.name into canonical
  from pg_catalog.pg_timezone_names z
  where lower(z.name) = lower(supplied)
    and z.name not like 'posix/%'
    and z.name not like 'right/%'
    and z.name <> 'Factory'
  order by z.name
  limit 1;

  if canonical is null then
    raise exception '% is not an IANA time zone', supplied using errcode = 'check_violation';
  end if;

  -- Stored in the spelling the tz database uses, so every reader gets a name
  -- their own runtime recognises.
  new := jsonb_populate_record(new, jsonb_build_object(tg_argv[0], canonical));
  return new;
end;
$$;

comment on function public.enforce_iana_zone() is
  'Rejects a time zone the database does not know. A trigger rather than a check because pg_timezone_names is not immutable.';

revoke all on function public.enforce_iana_zone() from public;
revoke all on function public.enforce_iana_zone() from anon, authenticated;

-- supabase/sql/functions/public/enforce_member_cap.sql
-- ---------------------------------------------------------------------------
-- The member cap, and the owner's membership.
--
-- Both are triggers rather than checks because both are statements about a
-- table, not about a row.
-- ---------------------------------------------------------------------------

create or replace function public.enforce_member_cap()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  active_count integer;
begin
  if new.status <> 'active' then
    return new;
  end if;

  -- `for update` on the circle serialises concurrent joins: two people
  -- redeeming the last seat at once would otherwise both count eleven.
  perform 1 from public.circles where id = new.circle_id for update;

  select count(*) into active_count
  from public.circle_members
  where circle_id = new.circle_id
    and status = 'active'
    and (tg_op = 'INSERT' or user_id <> new.user_id);

  if active_count >= public.member_cap() then
    raise exception 'circle % already has the maximum of % active members',
      new.circle_id, public.member_cap()
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

comment on function public.enforce_member_cap() is
  'Member cap of 12 (spec §5.2). A trigger rather than a check because the rule is about the table, not the row.';

revoke all on function public.enforce_member_cap() from public;
revoke all on function public.enforce_member_cap() from anon, authenticated;

-- supabase/sql/functions/public/enforce_owner_is_member.sql
create or replace function public.enforce_owner_is_member()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.circle_members
    where circle_id = new.id
      and user_id = new.owner_user_id
      and status = 'active'
  ) then
    raise exception 'circle % owner % must be an active member', new.id, new.owner_user_id
      using errcode = 'foreign_key_violation';
  end if;
  return new;
end;
$$;

comment on function public.enforce_owner_is_member() is
  'The owner is a member (architecture §8.2). Deferred to the end of the transaction so create_circle can insert the circle and the membership in either order.';

revoke all on function public.enforce_owner_is_member() from public;
revoke all on function public.enforce_owner_is_member() from anon, authenticated;

-- supabase/sql/functions/public/enforce_owner_stays_member.sql
-- The same invariant from the other side.
--
-- Watching `circles` alone leaves it true only at the moment a circle is
-- created: removing the owner's membership later empties the ownership without
-- touching the circles row, `auth_is_owner` goes permanently false, and every
-- owner-only operation on that circle is refused for good. An owner who wants
-- out hands the circle over first — that is a real operation with its own
-- checks (spec §9), not a side effect of leaving.

create or replace function public.enforce_owner_stays_member()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  row_circle uuid := coalesce(new.circle_id, old.circle_id);
  row_user uuid := coalesce(new.user_id, old.user_id);
begin
  -- The circle itself may have gone in this transaction, taking its members
  -- with it. Nothing to protect then.
  if not exists (
    select 1 from public.circles c
    where c.id = row_circle and c.owner_user_id = row_user
  ) then
    return null;
  end if;

  if not exists (
    select 1 from public.circle_members m
    where m.circle_id = row_circle and m.user_id = row_user and m.status = 'active'
  ) then
    raise exception 'circle % cannot remove its owner %; hand the circle over first',
      row_circle, row_user
      using errcode = 'foreign_key_violation';
  end if;

  return null;
end;
$$;

comment on function public.enforce_owner_stays_member() is
  'An owner stays an active member. Deferred, so a hand-off may change the owner and the membership in either order within one transaction.';

revoke all on function public.enforce_owner_stays_member() from public;
revoke all on function public.enforce_owner_stays_member() from anon, authenticated;

-- supabase/sql/functions/public/enforce_plan_deadline.sql
create or replace function public.enforce_plan_deadline()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  latest_start timestamptz := public.plan_last_possible_start(
    new.window_end, new.daily_end_local, new.duration_minutes, new.time_zone
  );
begin
  if new.response_deadline > latest_start then
    raise exception 'response deadline % is after the last possible start %',
      new.response_deadline, latest_start
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

comment on function public.enforce_plan_deadline() is
  'A deadline never runs past the last possible start (spec §5.3): replies that arrive once the plan cannot happen are replies to nothing.';

revoke all on function public.enforce_plan_deadline() from public;
revoke all on function public.enforce_plan_deadline() from anon, authenticated;

-- supabase/sql/functions/public/enforce_state_through_transition.sql
-- ---------------------------------------------------------------------------
-- Nothing else writes `state`.
--
-- Two mechanisms, because neither covers the other's case.
--
-- **A column privilege**: `update (state)` on `public.plans` is revoked from
-- `service_role` where the table is defined. That is the caller
-- the Edge Functions run as, and it is the one that matters: a `set_config`
-- marker is a *convention*, and any caller that can update the table can set it
-- first. Privileges cannot be manufactured by the code they restrain.
--
-- **The trigger**, for the case a privilege cannot reach: the table's owner,
-- which is `postgres` — migrations, psql, and `transition_plan` itself. The
-- marker is honest there, because at that point the caller is trusted and what
-- is being prevented is a mistake rather than an attack.
-- ---------------------------------------------------------------------------

create or replace function public.enforce_state_through_transition()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.state is distinct from old.state
     and coalesce(current_setting('circles.in_transition', true), '') <> 'on' then
    raise exception 'plans.state is written only by planning.transition_plan()'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

comment on function public.enforce_state_through_transition() is
  'Refuses any update to plans.state from outside planning.transition_plan(), which sets circles.in_transition for the length of its own transaction.';

revoke all on function public.enforce_state_through_transition() from public;
revoke all on function public.enforce_state_through_transition() from anon, authenticated;

-- supabase/sql/functions/public/enforce_window_shape.sql
-- Alignment is judged in the **plan's zone**, not UTC. The ticket's sketch had
-- `extract(minute from starts_at at time zone 'UTC') in (0, 30)`, and that is
-- wrong for every zone that is not a whole hour off UTC: Kathmandu is +05:45,
-- so a window painted 09:00–10:00 there is 03:15–04:15 UTC and would have been
-- refused, while 09:15 local would have passed. S1-03 hit exactly this in the
-- domain, and the database has to agree with it.

create or replace function public.enforce_window_shape()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  response public.plan_responses;
  plan public.plans;
  local_start timestamp;
  local_end timestamp;
  day date;
  day_band_start timestamp;
  day_band_end timestamp;
begin
  select * into response from public.plan_responses r where r.id = new.response_id;
  select * into plan from public.plans p where p.id = response.plan_id;

  -- Windows belong to a `windows` answer and nothing else: a `not_this_time`
  -- with a window attached would be availability the person had withdrawn.
  if response.status <> 'windows' then
    raise exception 'a % response carries no windows', response.status
      using errcode = 'check_violation';
  end if;

  local_start := new.starts_at at time zone plan.time_zone;
  local_end := new.ends_at at time zone plan.time_zone;

  if extract(minute from local_start)::integer % 30 <> 0
     or extract(second from local_start) <> 0
     or extract(minute from local_end)::integer % 30 <> 0
     or extract(second from local_end) <> 0 then
    raise exception 'window %–% is not on a half hour in %', new.starts_at, new.ends_at, plan.time_zone
      using errcode = 'check_violation';
  end if;

  -- Inside the plan: the whole window fits the band of the day it starts on.
  -- Judged on the local clock so the day the clocks change reads the way the
  -- person saw it, and the band end may be 1440 — midnight, which rolls into
  -- the next date and is why the end is compared as an instant rather than as
  -- minutes-of-day.
  --
  -- One day, deliberately. The first version checked the end only when it fell
  -- on the same date as the start, so 18:30 Thursday to 20:30 Friday sailed
  -- through with the whole night inside it — availability the person never
  -- painted, which the engine would then have offered. The domain's
  -- `isWithinPlan` is containment in one day's band; this is the same rule.
  day := local_start::date;
  day_band_start := day::timestamp + make_interval(mins => plan.daily_start_local);
  day_band_end := day::timestamp + make_interval(mins => plan.daily_end_local);
  if day < plan.window_start or day > plan.window_end
     or local_start < day_band_start or local_end > day_band_end then
    raise exception 'window %–% lies outside the plan''s daily band', new.starts_at, new.ends_at
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

comment on function public.enforce_window_shape() is
  'Half-hour aligned in the plan''s zone, inside the plan''s window and band, and attached to a `windows` response. Mirrors normaliseWindows() in packages/domain/src/availability/windows.ts.';

revoke all on function public.enforce_window_shape() from public;
revoke all on function public.enforce_window_shape() from anon, authenticated;

-- supabase/sql/functions/public/handle_new_user.sql
-- ---------------------------------------------------------------------------
-- The signup trigger.
--
-- `is_permanent` is derived from the auth row rather than trusted from a
-- client: an anonymous session that could set its own flag would walk straight
-- through the organiser gate.
-- ---------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (user_id, display_name, time_zone, is_permanent)
  values (
    new.id,
    -- A name the person gave, if they gave one. Never an email address or any
    -- part of one: display names are shown to the whole circle (§14).
    coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), 'Guest'),
    coalesce(nullif(trim(new.raw_user_meta_data ->> 'time_zone'), ''), 'UTC'),
    -- The column, not the `raw_app_meta_data` copy: it is what GoTrue sets and
    -- what the JWT claim is derived from, so this cannot disagree with the gate.
    not coalesce(new.is_anonymous, false)
  )
  on conflict (user_id) do nothing;
  return new;
end;
$$;

comment on function public.handle_new_user() is
  'Creates the profile for a new auth user, with is_permanent derived from the auth row rather than supplied by the client.';

revoke all on function public.handle_new_user() from public;
revoke all on function public.handle_new_user() from anon, authenticated;

-- supabase/sql/functions/public/handle_user_updated.sql
-- Saving your place *updates* the auth row; it does not insert one.
--
-- `linkIdentity` attaches Apple, Google or an email identity to the anonymous
-- user already signed in, so an insert-only trigger would leave the profile
-- saying `is_permanent = false` forever. The JWT would be right and the durable
-- record wrong, which is the direction that bites later: reattachment must
-- never target a saved-place member, and it reads the record.
--
-- One direction only. There is no path back from a saved place to an anonymous
-- session, and a trigger that could take one would be a way to shed an
-- organiser role by unlinking.

create or replace function public.handle_user_updated()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not new.is_anonymous then
    update public.profiles p
    set is_permanent = true
    where p.user_id = new.id and not p.is_permanent;
  end if;
  return new;
end;
$$;

comment on function public.handle_user_updated() is
  'Marks a profile permanent when the auth row stops being anonymous (linkIdentity). One direction only: a saved place cannot be given back.';

revoke all on function public.handle_user_updated() from public;
revoke all on function public.handle_user_updated() from anon, authenticated;

