-- supabase/sql/functions/public/on_member_removed.sql
-- ---------------------------------------------------------------------------
-- Removal: every consequence, in one trigger.
--
-- Spec §4.5 — a removed member "loses circle and plan access immediately;
-- historic aggregate attendance may remain; their availability is deleted."
-- Four things follow, and they are here together rather than in four triggers
-- because they cannot be correct separately:
--
--   * their responses and windows go — the cascade takes the windows, and the
--     bump triggers stale every candidate set that counted them;
--   * they leave the participant list of every plan revision still open, so
--     the dispatcher stops treating them as a non-responder;
--   * a `ready` plan they had answered goes back to `collecting`, because its
--     set may have needed them for quorum, and `confirm` must not lock in a
--     time that depended on somebody who has left;
--   * on a confirmation still ahead, `going` or `unknown` becomes `cant` — a
--     `going` from them would keep them in "5 going" and on the reminder list.
--     History is untouched: answers about evenings that have happened, and
--     rows on closed confirmations, stay exactly as they were.
--
-- The plan rows are locked first, so a removal racing a first answer cannot
-- let the answer land behind it.
-- ---------------------------------------------------------------------------

create or replace function public.on_member_removed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  affected uuid;
begin
  if new.status <> 'removed' or old.status = 'removed' then
    return new;
  end if;

  perform 1 from public.plans p where p.circle_id = new.circle_id for update;

  delete from public.plan_responses r
  using public.plans p
  where r.plan_id = p.id
    and p.circle_id = new.circle_id and r.user_id = new.user_id;

  update public.plans p
  set input_version = p.input_version + 1
  where p.circle_id = new.circle_id
    and p.state in ('seeking', 'collecting', 'ready');

  delete from public.plan_participants pp
  using public.plans p
  where pp.plan_id = p.id and pp.revision = p.revision and pp.user_id = new.user_id
    and p.circle_id = new.circle_id
    and p.state in ('seeking', 'collecting', 'ready');

  for affected in
    select p.id from public.plans p
    where p.circle_id = new.circle_id and p.state = 'ready'
  loop
    perform planning.transition_plan(affected, 'candidates_gone', new.user_id);
  end loop;

  -- Not coming to anything still ahead. History is left exactly as it was:
  -- `was_there` and `missed`, rows on closed confirmations, and rows on a
  -- meetup that has ended but not yet been reported on — `active` alone does
  -- not mean "ahead", and a `going` from last Thursday is part of the historic
  -- aggregate §4.5 lets remain.
  update public.attendance a
  set status = 'cant', updated_at = now()
  from public.meetup_confirmations c
  join public.plans p on p.id = c.plan_id
  where a.confirmation_id = c.id
    and a.user_id = new.user_id
    and p.circle_id = new.circle_id
    and c.status = 'active'
    and c.ends_at > now()
    and a.status in ('going', 'unknown');

  return new;
end;
$$;

revoke all on function public.on_member_removed() from public;
revoke all on function public.on_member_removed() from anon, authenticated;

-- supabase/sql/functions/public/plan_last_possible_start.sql
-- ---------------------------------------------------------------------------
-- The deadline is never after the last possible start.
--
-- Architecture §8.2 lists it as a constraint on `plans`, and it cannot be a
-- `check`: the last possible start is a wall-clock time in the plan's zone, and
-- `at time zone` is stable rather than immutable — the tz database can change
-- under a stored row.
-- ---------------------------------------------------------------------------

create or replace function public.plan_last_possible_start(
  window_end date,
  daily_end_local integer,
  duration_minutes integer,
  time_zone text
)
returns timestamptz
language sql
stable
set search_path = ''
as $$
  -- Minutes added to midnight rather than a constructed time, so a band ending
  -- at 1440 rolls into the next day instead of failing to be a clock reading.
  select (
    plan_last_possible_start.window_end::timestamp
      + make_interval(mins => plan_last_possible_start.daily_end_local
                              - plan_last_possible_start.duration_minutes)
  ) at time zone plan_last_possible_start.time_zone;
$$;

comment on function public.plan_last_possible_start(date, integer, integer, text) is
  'The latest instant the meetup could still begin. Mirrors lastPossibleStart() in packages/domain/src/planning/deadline.ts.';

revoke all on function public.plan_last_possible_start(date, integer, integer, text) from public;
revoke all on function public.plan_last_possible_start(date, integer, integer, text)
  from anon, authenticated;

-- supabase/sql/functions/public/replace_response.sql
-- Parameters carry a `p_` prefix, as `transition_plan`'s do: a parameter named
-- `plan_id` is ambiguous against the column of the same name inside
-- `on conflict (plan_id, …)`, and plpgsql refuses to guess.

create or replace function public.replace_response(
  p_plan_id uuid,
  -- The revision the client is answering. Required, because an answer is an
  -- answer to a *question*, and the question can change while a draft sits on
  -- a phone with no signal (spec §5.5). Storing revision 1's windows under
  -- revision 2 would be silently answering dates the person never saw.
  p_revision integer,
  p_status text,
  p_windows jsonb default '[]'::jsonb,
  p_used_calendar_overlay boolean default false
)
returns public.plan_responses
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := (select auth.uid());
  plan public.plans;
  response public.plan_responses;
begin
  if caller is null then
    raise exception 'not signed in' using errcode = 'insufficient_privilege';
  end if;

  -- The lock: two submissions from one person's two devices would otherwise
  -- interleave their window deletes and inserts.
  select * into plan from public.plans p where p.id = p_plan_id for update;
  if not found or not public.auth_is_member(plan.circle_id) then
    -- The same answer for "no such plan" and "not your circle": telling them
    -- apart would confirm a plan id exists.
    raise exception 'plan not found' using errcode = 'insufficient_privilege';
  end if;

  -- The question moved on. Refused with its own code so the client can fetch
  -- the plan again and re-ask, rather than being told its window was malformed.
  if p_revision <> plan.revision then
    raise exception 'stale_revision: answered % but the plan is at %', p_revision, plan.revision
      using errcode = 'serialization_failure';
  end if;

  -- Addressed to this person: spec §9 makes joining an active plan an opt-in,
  -- and answering a question you were not asked is how a newcomer becomes a
  -- non-responder to it.
  if not exists (
    select 1 from public.plan_participants pp
    where pp.plan_id = plan.id and pp.revision = plan.revision and pp.user_id = caller
  ) then
    raise exception 'not a participant in this plan' using errcode = 'insufficient_privilege';
  end if;

  -- "Editing is allowed until confirmation or the deadline" (spec §5.5).
  if plan.state not in ('collecting', 'ready') then
    raise exception 'replies are closed: plan is %', plan.state using errcode = 'check_violation';
  end if;
  if now() >= plan.response_deadline then
    raise exception 'replies closed at %', plan.response_deadline using errcode = 'check_violation';
  end if;

  -- A SQL null is not an empty list: `jsonb_array_length(null)` is null, and
  -- `null = 0` is not true, so a null slipped past this check and produced a
  -- `windows` answer with no windows. Coalesce first, and insist on an array.
  p_windows := coalesce(p_windows, '[]'::jsonb);
  if jsonb_typeof(p_windows) <> 'array' then
    raise exception 'windows must be a list' using errcode = 'check_violation';
  end if;

  -- The domain's union, enforced: only a `windows` answer carries windows, and
  -- a `windows` answer carries at least one.
  if p_status = 'windows' and jsonb_array_length(p_windows) = 0 then
    raise exception 'a windows response needs at least one window' using errcode = 'check_violation';
  end if;
  if p_status <> 'windows' and jsonb_array_length(p_windows) > 0 then
    raise exception 'a % response carries no windows', p_status
      using errcode = 'check_violation';
  end if;

  -- One bump for the whole answer, at the end; the row triggers stand down
  -- for the length of this function.
  perform set_config('circles.in_replace_response', 'on', true);

  -- Replace, not merge. The person's answer is the whole list they sent.
  delete from public.willing_windows ww
  using public.plan_responses r
  where ww.response_id = r.id
    and r.plan_id = plan.id and r.revision = plan.revision and r.user_id = caller;

  insert into public.plan_responses (plan_id, revision, user_id, status, used_calendar_overlay, submitted_at)
  values (plan.id, plan.revision, caller, p_status, p_used_calendar_overlay, now())
  on conflict (plan_id, revision, user_id) do update
    set status = excluded.status,
        used_calendar_overlay = excluded.used_calendar_overlay,
        submitted_at = excluded.submitted_at
  returning * into response;

  insert into public.willing_windows (response_id, starts_at, ends_at)
  select response.id, (w ->> 'start')::timestamptz, (w ->> 'end')::timestamptz
  from jsonb_array_elements(p_windows) as w;

  perform set_config('circles.in_replace_response', 'off', true);
  update public.plans p set input_version = p.input_version + 1 where p.id = plan.id;

  -- Architecture §8.3: `ready ─(response change)─▶ collecting`. A ready plan
  -- whose answers just moved has no current candidate set — `confirm` would
  -- refuse the old one as stale while every state-driven screen and job still
  -- saw "ready". `candidates_gone` is the engine's verdict and carries no
  -- actor guard, so the person who answered can be the one to fire it; the
  -- recalculation brings it back to ready.
  if plan.state = 'ready' then
    perform planning.transition_plan(plan.id, 'candidates_gone', caller);
  end if;

  -- `availability.response_submitted` is written to `jobs.outbox` by the row
  -- trigger on `plan_responses` (0006), in this transaction: one event per
  -- answer, because the upsert above touches the row exactly once.

  return response;
end;
$$;

comment on function public.replace_response(uuid, integer, text, jsonb, boolean) is
  'Replaces the caller''s answer to the given plan revision atomically; refuses a revision the plan has moved past. The only write path for responses and windows (ADR 0013).';

revoke all on function public.replace_response(uuid, integer, text, jsonb, boolean) from public;
revoke all on function public.replace_response(uuid, integer, text, jsonb, boolean) from anon, authenticated;
grant execute on function public.replace_response(uuid, integer, text, jsonb, boolean) to authenticated;

-- supabase/sql/functions/public/report_outcome.sql
-- The one way a client reports an outcome (architecture §8.4: attendance is
-- the only confirmation table a member writes directly). The actor is
-- `auth.uid()`, never a parameter, and `reported_at` is the server's clock.
-- The organiser check here is the cheap, early one; the one that counts —
-- organiser *and still a member* — is `transition_plan`'s, reached through the
-- trigger, and it is not duplicated.

create or replace function public.report_outcome(
  p_confirmation_id uuid,
  p_outcome text,
  p_note text default null,
  p_moved_outside boolean default null
)
returns public.outcome_reports
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  organiser uuid;
  report public.outcome_reports;
begin
  if actor is null then
    raise exception 'report_outcome requires a signed-in actor' using errcode = 'insufficient_privilege';
  end if;

  select p.organiser_user_id into organiser
  from public.meetup_confirmations c
  join public.plans p on p.id = c.plan_id
  where c.id = p_confirmation_id;

  if organiser is distinct from actor then
    raise exception 'only the organiser reports an outcome' using errcode = 'insufficient_privilege';
  end if;

  insert into public.outcome_reports (confirmation_id, reported_by, outcome, note, moved_outside)
  values (p_confirmation_id, actor, p_outcome, p_note, p_moved_outside)
  returning * into report;

  return report;
end;
$$;

comment on function public.report_outcome(uuid, text, text, boolean) is
  'The organiser''s answer to "did this catch-up happen?". The only client write path to outcome_reports; the insert trigger does the rest.';

grant execute on function public.report_outcome(uuid, text, text, boolean) to authenticated;
revoke all on function public.report_outcome(uuid, text, text, boolean) from public;
revoke all on function public.report_outcome(uuid, text, text, boolean) from anon;

-- supabase/sql/functions/public/supersede_on_leaving_confirmed.sql
-- ---------------------------------------------------------------------------
-- Supersede on reschedule; cancel on cancel.
--
-- A trigger on `plans`, so that leaving `confirmed` by any transition takes
-- the active confirmation with it in the same statement. `transition_plan`
-- need not know confirmations exist, and there is no window in which a plan is
-- back in `collecting` with a confirmation still `active`.
-- ---------------------------------------------------------------------------

create or replace function public.supersede_on_leaving_confirmed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.state <> 'confirmed' or new.state = 'confirmed' then
    return new;
  end if;

  -- `reopen` bumps the revision and goes to collecting; `cancel` goes to
  -- cancelled. `report_outcome` goes to completed, and `apply_outcome` has
  -- normally closed the confirmation already with the outcome's own status —
  -- but a `report_outcome` applied directly, without a report, must not leave a
  -- completed plan with an active confirmation, so this closes it too.
  update public.meetup_confirmations c
  set status = case new.state when 'cancelled' then 'cancelled' when 'completed' then 'completed' else 'superseded' end,
      superseded_at = now(),
      superseded_reason = case new.state when 'cancelled' then 'cancel' when 'completed' then 'outcome' else 'reopen' end
  where c.plan_id = new.id
    and c.revision = old.revision
    and c.status = 'active';

  return new;
end;
$$;

comment on function public.supersede_on_leaving_confirmed() is
  'Reschedule supersedes, cancel cancels, never mutates (architecture §6.2). Mirrors supersede() in the domain.';

revoke all on function public.supersede_on_leaving_confirmed() from public;
revoke all on function public.supersede_on_leaving_confirmed() from anon, authenticated;

-- supabase/sql/functions/public/sync_member_names.sql
-- ---------------------------------------------------------------------------
-- Renaming.
--
-- The roster shows `display_name_snapshot` and `member_profiles` shows
-- `profiles.display_name`, and the uniqueness index only covers the first. A
-- member could therefore rename themselves to a co-member's name: the index saw
-- nothing change, and the circle showed two people with one name.
--
-- So while a membership is active its snapshot *follows* the profile, and the
-- index refuses the rename outright when it would collide. The snapshot stops
-- following at the moment of removal, which is what it was always for: a
-- removed member's history keeps the name they had.
-- ---------------------------------------------------------------------------

create or replace function public.sync_member_names()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.circle_members m
  set display_name_snapshot = new.display_name
  where m.user_id = new.user_id
    and m.status = 'active'
    and m.display_name_snapshot is distinct from new.display_name;
  return new;
end;
$$;

comment on function public.sync_member_names() is
  'Keeps an active membership''s name in step with the profile, so the uniqueness index sees a rename. Frozen on removal.';

revoke all on function public.sync_member_names() from public;
revoke all on function public.sync_member_names() from anon, authenticated;

